class Board:
    def __init__(self, name, port, baud):
        self.name = name
        self.port = serial.Serial()
        self.port.port = port
        self.port.baudrate = baud
        self.port.timeout = 0.05
        self.port.write_timeout = 1.0
        self.port._dtr_state = False
        self.port._rts_state = False
        self.port.open()
        self.port.dtr = False
        self.port.rts = False
        self.port.reset_input_buffer()
        self.pending = ""
        self.lines = []
        self.lock = threading.Lock()
        self.lines_q = queue.Queue()
        self.stop_event = threading.Event()
        self.reader = None

    def write(self, text):
        with self.lock:
            self.port.write(text.encode("utf-8", "replace"))

    def command(self, text):
        self.write(text + "\r\n")

    def read_once(self):
        with self.lock:
            data = self.port.read(4096)
        if not data:
            return []
        self.pending += data.decode("utf-8", "replace")
        ready = []
        while "\n" in self.pending:
            line, self.pending = self.pending.split("\n", 1)
            line = line.rstrip("\r")
            ready.append(line)
        return ready

    def start_reader(self):
        if self.reader is not None:
            return

        def run():
            while not self.stop_event.is_set():
                try:
                    for line in self.read_once():
                        self.lines_q.put(line)
                except Exception:
                    break

        self.reader = threading.Thread(target=run, daemon=True)
        self.reader.start()

    def next_line(self):
        try:
            return self.lines_q.get_nowait()
        except queue.Empty:
            return None

    def close(self):
        self.stop_event.set()
        if self.reader is not None:
            self.reader.join(timeout=1.0)
        self.port.close()


def wait_prompt(board, timeout=30):
    board.start_reader()
    end = time.time() + timeout
    while time.time() < end:
        board.command("")
        end_read = time.time() + 0.25
        while time.time() < end_read:
            line = board.next_line()
            if line is None:
                time.sleep(0.005)
                continue
            if VERBOSE and line:
                print(f"[{board.name}] {line}")
            if "nsh>" in line:
                return True
        time.sleep(0.02)
    return False


def parse_frame(line):
    marker = line.find(PREFIX)
    if marker < 0:
        return None
    text = line[marker + len(PREFIX):].strip()
    try:
        data = bytes.fromhex(text)
    except ValueError:
        return None
    if len(data) < HEADER.size:
        return None
    values = HEADER.unpack_from(data, 0)

