  fill_rect(10, BODY_Y + 44, UI_W - 20, 148, C_PANEL2);
  frame_rect(10, BODY_Y + 44, UI_W - 20, 148, C_LINE);

  fill_rect(22, BODY_Y + 56, 74, 20, C_BTN);
  frame_rect(22, BODY_Y + 56, 74, 20, C_LINE2);
