void jx_ui_wave(const int16_t *pcm, int n)
{
  if (B == NULL || pcm == NULL || n <= 0) { return; }

  if (n > WAVE_N)
    {
      int step = n / WAVE_N;

      for (int i = 0; i < WAVE_N; i++) { B->wave[i] = pcm[i * step]; }
      B->wave_n = WAVE_N;
    }
  else
    {
      for (int i = 0; i < n; i++) { B->wave[i] = pcm[i]; }
      B->wave_n = n;
    }
