  SPI_SETMODE(dev->spi, CONFIG_LCD_ST7789_SPIMODE);
  SPI_SETBITS(dev->spi, LCD_ST7789_SPI_BITS);
  SPI_SETFREQUENCY(dev->spi, CONFIG_LCD_ST7789_FREQUENCY);
  SPI_SELECT(dev->spi, SPIDEV_DISPLAY(0), true);

