                       (uint16_t)buff[j + 1 + (i * (size + skip))];
          rowbuff[j + 1] = LCD_ST7789_DATA_PREFIX |
                           (uint16_t)buff[j + (i * (size + skip))];
        }

      SPI_SNDBLOCK(dev->spi, rowbuff, size);
