    print("-" * 100)
    for s in sorted(sessions, key=lambda x: x.get("last_event_at") or ""):
        sid = (s["session_id"] or "")[:38]
        tool = s.get("tool", "")[:10]
        last = s.get("last_event_at", "")[:25]
        cnt = s.get("event_count", 0)
        model = s.get("model", "")
        print(f"{sid:<40} {tool:<12} {last:<26} {cnt:>6}  {model}")
    return 0


def load_backfill_env() -> tuple[str, str] | None:
    env_vars = subprocess.check_output(
        ["bash", "-c",
         "source ~/.claude/contest-collector.env 2>/dev/null && "
         "echo \"TEAM_ID=${TEAM_ID:-}\" && echo \"GITHUB_LOGIN=${GITHUB_LOGIN:-}\""],
        text=True,
    ).strip()
    env_map = dict(line.split("=", 1) for line in env_vars.splitlines() if "=" in line)
    team_id = env_map.get("TEAM_ID", "").strip()
    github_login = env_map.get("GITHUB_LOGIN", "").strip()
    if not team_id:
        sys.stderr.write("TEAM_ID not found. Run install.sh first.\n")
        return None
    if not github_login:
        sys.stderr.write("GITHUB_LOGIN not found in ~/.claude/contest-collector.env. "
                         "Re-run install.sh with --github-login <your-name>.\n")
        return None
    return team_id, github_login


def backfill_claude_code(dest: Path, team_id: str, github_login: str) -> int:
    claude_projects = Path.home() / ".claude" / "projects"
    if not claude_projects.is_dir():
        return 0
    skill_root = Path(__file__).resolve().parent.parent
    core_py = skill_root / "adapters" / "shared" / "snapshot_core.py"
    if not core_py.exists():
        return 0
    transcripts = sorted(claude_projects.glob("*/*.jsonl"))
    if not transcripts:
        return 0
    print(f"[claude-code] scanning {len(transcripts)} transcript(s) in {claude_projects}")
    child_env = {**subprocess.os.environ, "TEAM_ID": team_id,
                 "GITHUB_LOGIN": github_login, "CWD": str(dest)}
    success = 0
    for t in transcripts:
        sid = t.stem
        payload = json.dumps({
            "session_id": sid, "cwd": str(dest),
            "transcript_path": str(t), "hook_event_name": "SessionEnd",
        })
        try:
            result = subprocess.run(
                [sys.executable, str(core_py), "--tool", "claude-code"],
                input=payload, text=True, capture_output=True,
                env=child_env, cwd=str(dest),
            )
            if result.returncode == 0 and "captured" in result.stderr:
                success += 1
                print(f"  [claude-code] {sid[:12]}  captured")
        except Exception as e:
            print(f"  [claude-code] {sid[:12]}  ERROR: {e}")
    return success


def _millis_to_iso(millis) -> str:
    try:
        dt = datetime.fromtimestamp(int(millis) / 1000, tz=timezone.utc)
        return dt.strftime("%Y-%m-%dT%H:%M:%S.") + f"{dt.microsecond // 1000:03d}Z"
    except Exception:
        return datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.000Z")


def _sqlite_session_to_events(conn, session_id, team_id, github_login, tool):
    messages = conn.execute(
        "SELECT id, time_created, data FROM message WHERE session_id=? ORDER BY time_created, id",
        (session_id,),
    ).fetchall()
    if not messages:
        return []
    events = []
    seq = 0
    for msg in messages:
        try:
            mdata = json.loads(msg["data"])
        except Exception:
            continue
        role = mdata.get("role", "user")
        if role not in ("user", "assistant", "system", "tool"):
            role = "user"
        ts = _millis_to_iso(msg["time_created"])
        model = (mdata.get("model") or {}).get("modelID")
        parts = conn.execute(
            "SELECT data FROM part WHERE message_id=? ORDER BY time_created, id",
            (msg["id"],),
        ).fetchall()
        text_chunks = []
        for p in parts:
            try:
                pdata = json.loads(p["data"])
            except Exception:
                continue
            if pdata.get("type") == "text":
                t = pdata.get("text", "")
                if t:
                    text_chunks.append(t)
        text = "\n".join(text_chunks).strip()
        if not text:
            continue
        ev = {
            "schema_version": "1.0", "session_id": session_id,
            "team_id": team_id, "github_login": github_login,
            "tool": tool, "seq": seq, "ts": ts, "role": role, "text": text,
        }
        if model and role == "assistant":
            ev["model"] = model
        events.append(ev)
        seq += 1
    return events


def _sqlite_write_manifest(dest, github_login, team_id, tool, session_id, events, rel_path):
    member_dir = dest / "logs" / github_login
    manifest_path = member_dir / "manifest.json"
    if manifest_path.exists():
        try:
            manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
        except Exception:
            manifest = {}
    else:
        manifest = {}
    manifest.setdefault("schema_version", "1.0")
    manifest["team_id"] = team_id
    manifest["github_login"] = github_login
    manifest.setdefault("generator", f"backfill-sqlite@{tool}")
    sessions = manifest.setdefault("sessions", [])
    entry = next((s for s in sessions if s.get("session_id") == session_id), None)
    new_entry = {
        "session_id": session_id, "tool": tool,
        "started_at": events[0]["ts"], "last_event_at": events[-1]["ts"],
        "event_count": len(events), "file_path": rel_path,
        "collection_mode": "backfill-sqlite", "health": "ok",
    }
    if entry:
        entry.update(new_entry)
    else:
        sessions.append(new_entry)
    manifest["updated_at"] = datetime.now(timezone.utc).isoformat()
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")


def _find_workspace_root(start: Path) -> Path | None:
    cur = start.resolve()
    for candidate in [cur, *cur.parents]:
        if (candidate / ".repo").is_dir():
            return candidate
    return None


def backfill_sqlite_db(db_path, tool, workspace_root, dest, team_id, github_login):
    if not db_path.is_file():
        return 0
    try:
        conn = sqlite3.connect(f"file:{db_path}?mode=ro", uri=True)
    except sqlite3.Error as e:
        sys.stderr.write(f"[{tool}] cannot open {db_path}: {e}\n")
        return 0
    conn.row_factory = sqlite3.Row
    workspace_str = str(workspace_root.resolve())
    try:
        rows = conn.execute(
            "SELECT id, directory FROM session ORDER BY time_created"
        ).fetchall()
    except sqlite3.Error as e:
        sys.stderr.write(f"[{tool}] cannot read session table: {e}\n")
        conn.close()
        return 0
    matched = [r for r in rows if r["directory"] and str(Path(r["directory"]).resolve()).startswith(workspace_str)]
    if not matched:
        conn.close()
        print(f"[{tool}] no sessions in workspace {workspace_root} (scanned {len(rows)})")
        return 0
    print(f"[{tool}] found {len(matched)} session(s) inside workspace (out of {len(rows)} total)")
    success = 0
    for s in matched:
        sid = s["id"]
        events = _sqlite_session_to_events(conn, sid, team_id, github_login, tool)
        if not events:
            continue
        date_str = events[0]["ts"][:10]
        rel_path = f"logs/{github_login}/{date_str}/{tool}__{sid}.jsonl"
        jsonl_path = dest / rel_path
        jsonl_path.parent.mkdir(parents=True, exist_ok=True)
        with jsonl_path.open("w", encoding="utf-8") as f:
            for e in events:
                f.write(json.dumps(e, ensure_ascii=False) + "\n")
        _sqlite_write_manifest(dest, github_login, team_id, tool, sid, events, rel_path)
        success += 1
        print(f"  [{tool}] {sid[:20]}  wrote {len(events)} event(s) -> {rel_path}")
    conn.close()
    return success


def cmd_backfill(args) -> int:
    dest = Path(args.dest) if args.dest else repo_root()
    if dest is None:
        sys.stderr.write("Cannot detect demo repo. "
                         "Run inside the repo or pass --dest.\n")
        return 2

    if args.force:
        staging = staging_root()
        if staging.exists():
            print(f"[--force] wiping staging at {staging}")
            shutil.rmtree(staging)

    env = load_backfill_env()
    if env is None:
        return 2
    team_id, github_login = env
    if getattr(args, "github_login", None):
        github_login = args.github_login

    workspace = _find_workspace_root(dest) or dest
    print(f"Destination: {dest}/logs/")
    print(f"Workspace:   {workspace}")
    print(f"GitHub login: {github_login}")
    print()

    source = getattr(args, "source", "all") or "all"
    total = 0
    if source in ("all", "claude"):
        total += backfill_claude_code(dest, team_id, github_login)
    if source in ("all", "sqlite", "opencode"):
        db = Path.home() / ".local" / "share" / "opencode" / "opencode.db"
        total += backfill_sqlite_db(db, "opencode", workspace, dest, team_id, github_login)
    if source in ("all", "sqlite", "mimocode"):
        db = Path.home() / ".local" / "share" / "mimocode" / "mimocode.db"
        total += backfill_sqlite_db(db, "mimocode", workspace, dest, team_id, github_login)
    if source in ("all", "cursor"):
        cursor_adapter = Path(__file__).resolve().parent.parent / \
            "adapters" / "cursor"
        sys.path.insert(0, str(cursor_adapter))
        try:
            import backfill_cursor
            total += backfill_cursor.backfill(dest, team_id, github_login)
        except ImportError as e:
            sys.stderr.write(f"[cursor] adapter import failed: {e}\n")
        finally:
            if str(cursor_adapter) in sys.path:
                sys.path.remove(str(cursor_adapter))
    if source in ("all", "codex"):
        codex_adapter = Path(__file__).resolve().parent.parent / \
            "adapters" / "codex"
        sys.path.insert(0, str(codex_adapter))
        try:
            import backfill_codex
            total += backfill_codex.backfill(dest, team_id, github_login)
        except ImportError as e:
            sys.stderr.write(f"[codex] adapter import failed: {e}\n")
        finally:
            if str(codex_adapter) in sys.path:
                sys.path.remove(str(codex_adapter))

    print(f"\nBackfill done: {total} session(s) imported.")
    if total > 0:
        print("Next: git add logs/ && git commit -s -m 'logs: backfill history' && git push")
    return 0


def main() -> int:
    p = argparse.ArgumentParser(
        description="Export AI Coding sessions from staging to demo repo logs/.",
        formatter_class=argparse.RawDescriptionHelpFormatter,
    )
    p.add_argument("--list", action="store_true",
                   help="List all sessions in staging without exporting.")
    p.add_argument("--latest", action="store_true",
                   help="Export only the most recent session.")
    p.add_argument("--session", metavar="SID",
                   help="Export a specific session by id.")
    p.add_argument("--today", action="store_true",
                   help="Export sessions from today (UTC).")
    p.add_argument("--since", metavar="DATE",
                   help="Export sessions since a date (YYYY-MM-DD).")
    p.add_argument("--all", action="store_true",
                   help="Export every session in staging.")
    p.add_argument("--backfill", action="store_true",
                   help="Scan Claude Code history (~/.claude/projects/) and "
                        "re-process all transcripts. Recovers sessions that "
                        "were created before the hook was installed.")
    p.add_argument("--source", metavar="SRC", default="all",
                   choices=["all", "claude", "sqlite", "opencode",
                            "mimocode", "cursor", "codex"],
                   help="With --backfill, which source to scan. "
                        "'all' (default) scans Claude Code + OpenCode + "
                        "MiMoCode + Cursor + Codex; "
                        "'claude' scans only ~/.claude/projects/; "
                        "'sqlite' scans OpenCode + MiMoCode SQLite; "
                        "'opencode' / 'mimocode' scans just that one; "
                        "'cursor' scans Cursor global + workspace state.vscdb; "
                        "'codex' scans $CODEX_HOME/sessions rollout files "
                        "(covers Codex CLI, IDE extension, and desktop app).")
    p.add_argument("--force", action="store_true",
                   help="With --backfill, wipe the local staging first so all "
                        "transcripts are re-processed even if they were "
                        "captured before. Useful after cleaning logs/ to "
                        "rebuild from scratch.")
    p.add_argument("--github-login", metavar="LOGIN",
                   help="Restrict to one member's sessions.")
    p.add_argument("--dest", metavar="PATH",
                   help="Destination repo path. Defaults to git rev-parse --show-toplevel.")
    p.add_argument("--dry-run", action="store_true",
                   help="Force preview mode, do not write.")
    p.add_argument("--confirm", action="store_true",
                   help="Required to actually export. Without it, the tool only previews.")
    args = p.parse_args()

    sessions = list_sessions(args.github_login)

    if args.list:
        return cmd_list(args, sessions)

    if args.backfill:
        return cmd_backfill(args)

    if not any([args.latest, args.session, args.today, args.since, args.all]):
        p.print_help()
        sys.stderr.write("\nNothing to do. Pick one of "
                         "--latest, --session, --today, --since, --all, --list, --backfill.\n")
        return 2

    selected = filter_sessions(sessions, args)
    if not selected:
        sys.stderr.write("No sessions matched.\n")
        return 1

    dest = Path(args.dest) if args.dest else repo_root()
    if dest is None:
        sys.stderr.write("Cannot detect demo repo. "
                         "Run inside the repo or pass --dest.\n")
        return 2

    preview_only = args.dry_run or not args.confirm
    rc = 0
    for s in selected:
        ok, msg = copy_session(s, dest, preview_only)
        prefix = "✅" if ok else "❌"
        print(f"{prefix} {s['session_id'][:12]}  {msg}")
        if not ok:
            rc = 1

    if preview_only:
        print(f"\n[preview] {len(selected)} session(s) shown above. "
              "Nothing was written.")
        print("Re-run with --confirm to actually export, e.g.:")
        if args.latest:
            print("  python3 tools/export-session.py --latest --confirm")
        elif args.session:
            print(f"  python3 tools/export-session.py --session {args.session} --confirm")
        elif args.today:
            print("  python3 tools/export-session.py --today --confirm")
        elif args.since:
            print(f"  python3 tools/export-session.py --since {args.since} --confirm")
        elif args.all:
            print("  python3 tools/export-session.py --all --confirm")
    else:
        print(f"\n{len(selected)} session(s) exported to {dest}/logs/")
        print("Next: git add logs/ && git commit && git push")

    return rc


if __name__ == "__main__":
    sys.exit(main())

#!/usr/bin/env python3
"""
contest-log-upload validation tool

Validate demo repo's logs/ directory:
  1. manifest.json conforms to manifest.schema.json
  2. Each line in every .jsonl file conforms to event.schema.json
  3. seq within each session is monotonic (tamper detection);
     a session may span several date files (pre-2026-07 collector
     versions split one session across daily files) - all files named
     <tool>__<sid>.jsonl are validated as one continuous seq stream
     and compared against the manifest's cumulative event_count
  4. Files declared in manifest actually exist, and vice versa;
     byte-identical duplicate lines (plugin re-export artifacts) are
     reported as warnings, only content-conflicting duplicates are
     anti-cheat errors
  5. team_id / tool consistency across files

Usage:
    validate-log.py <logs_dir>
    validate-log.py contest-demo-team-001-zhangsan/logs/

Exit codes:
    0  All passed
    1  Errors found
    2  Warnings found (non-fatal)
    3  Usage error (args / IO)
"""
from __future__ import annotations

import argparse
import json
import os
import re
import sys
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any, Iterable

try:
    from jsonschema import Draft7Validator
except ImportError:
    print(
        "ERROR: missing dependency 'jsonschema'. Install via: pip install jsonschema",
        file=sys.stderr,
    )
    sys.exit(3)


SCHEMA_DIR = Path(__file__).resolve().parent.parent / "schema"
EVENT_SCHEMA_PATH = SCHEMA_DIR / "event.schema.json"
MANIFEST_SCHEMA_PATH = SCHEMA_DIR / "manifest.schema.json"


@dataclass
class Report:
    errors: list[str] = field(default_factory=list)
    warnings: list[str] = field(default_factory=list)
    files_checked: int = 0
    events_checked: int = 0

    def err(self, msg: str) -> None:
        self.errors.append(msg)

    def warn(self, msg: str) -> None:
        self.warnings.append(msg)

    @property
    def has_errors(self) -> bool:
        return bool(self.errors)

    @property
    def has_warnings(self) -> bool:
        return bool(self.warnings)


def load_schema(path: Path) -> dict[str, Any]:
    if not path.exists():
        print(f"ERROR: schema not found: {path}", file=sys.stderr)
        sys.exit(3)
    with path.open("r", encoding="utf-8") as f:
        return json.load(f)


def validate_event(
    event: dict[str, Any],
    validator: Draft7Validator,
    line_no: int,
    file_label: str,
    report: Report,
) -> None:
    for err in validator.iter_errors(event):
        # jsonschema's absolute_path is a list of segments, not a JSONPath string;
        # we synthesize "$.foo[3].bar" form for human-readable error messages
        loc = "$" + "".join(
            f"[{p!r}]" if isinstance(p, int) else f".{p}" for p in err.absolute_path
        )
        report.err(f"{file_label}:{line_no}: {loc}: {err.message}")


def validate_jsonl_file(
    jsonl_path: Path,
    event_validator: Draft7Validator,
    expected_team_id: str,
    expected_github_login: str,
    expected_tool: str,
    expected_session_id: str,
    report: Report,
    seq_state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Validate a single .jsonl file. Returns stats {ts_min, ts_max, count}.

    seq_state carries the session-level seq ledger (seen seq -> raw line,
    last seq) so that a session split across several date files is checked
    as one continuous stream. Pass a fresh dict per session; files of the
    same session must share the same dict.
    """
    stats = {
        "ts_min": None,
        "ts_max": None,
        "count": 0,
    }
    if seq_state is None:
        seq_state = {"seen": {}, "last": -1}
    file_label = str(jsonl_path)

    if not jsonl_path.exists():
        report.err(f"{file_label}: file does not exist (declared in manifest)")
        return stats

    try:
        content = jsonl_path.read_text(encoding="utf-8")
    except Exception as e:
        report.err(f"{file_label}: cannot read: {e}")
        return stats

    if not content.endswith("\n"):
        report.warn(f"{file_label}: file does not end with newline (spec violation)")

    for line_no, line in enumerate(content.splitlines(), start=1):
        if not line.strip():
            report.warn(f"{file_label}:{line_no}: empty line in JSONL")
            continue

        try:
            event = json.loads(line)
        except json.JSONDecodeError as e:
            report.err(f"{file_label}:{line_no}: invalid JSON: {e.msg}")
            continue

        if not isinstance(event, dict):
            report.err(f"{file_label}:{line_no}: expected object, got {type(event).__name__}")
            continue

        validate_event(event, event_validator, line_no, file_label, report)

        if event.get("team_id") and event["team_id"] != expected_team_id:
            report.err(
                f"{file_label}:{line_no}: team_id mismatch: got {event['team_id']!r}, "
                f"expected {expected_team_id!r}"
            )
        if event.get("github_login") and event["github_login"] != expected_github_login:
            report.err(
                f"{file_label}:{line_no}: github_login mismatch: got {event['github_login']!r}, "
                f"expected {expected_github_login!r}"
            )
        if event.get("tool") and event["tool"] != expected_tool:
            report.err(
                f"{file_label}:{line_no}: tool mismatch: got {event['tool']!r}, "
                f"expected {expected_tool!r}"
            )
        if event.get("session_id") and event["session_id"] != expected_session_id:
            report.err(
                f"{file_label}:{line_no}: session_id mismatch: got {event['session_id']!r}, "
                f"expected {expected_session_id!r}"
            )

        if "seq" in event:
            seq = event["seq"]
            first_line = seq_state["seen"].get(seq)
            if first_line is not None:
                if first_line == line:
                    # Byte-identical re-append: early collector versions
                    # re-exported overlapping transcript ranges into the
                    # same file. Harmless artifact, not tampering.
                    report.warn(
                        f"{file_label}:{line_no}: duplicate identical line seq={seq} "
                        f"(plugin re-export artifact)"
                    )
                else:
                    report.err(
                        f"{file_label}:{line_no}: duplicate seq={seq} with different "
                        f"content (anti-cheat violation)"
                    )
            else:
                seq_state["seen"][seq] = line
                if seq <= seq_state["last"]:
                    report.err(
                        f"{file_label}:{line_no}: seq={seq} not monotonically increasing "
                        f"(previous={seq_state['last']}, anti-cheat violation)"
                    )
                seq_state["last"] = max(seq_state["last"], seq)

        if "ts" in event:
            ts = event["ts"]
            if stats["ts_min"] is None or ts < stats["ts_min"]:
                stats["ts_min"] = ts
            if stats["ts_max"] is None or ts > stats["ts_max"]:
                stats["ts_max"] = ts

        stats["count"] += 1
        report.events_checked += 1

    report.files_checked += 1
    return stats


def _validate_one_member(
    member_dir: Path,
    repo_root: Path,
    manifest_validator: Draft7Validator,
    event_validator: Draft7Validator,
    report: Report,
) -> None:
    manifest_path = member_dir / "manifest.json"

    if not manifest_path.exists():
        report.err(f"{manifest_path}: manifest.json not found in member directory")
        return

    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as e:
        report.err(f"{manifest_path}: invalid JSON: {e}")
        return

    for err in manifest_validator.iter_errors(manifest):
        loc = "$" + "".join(
            f"[{p!r}]" if isinstance(p, int) else f".{p}" for p in err.absolute_path
        )
        report.err(f"{manifest_path}: {loc}: {err.message}")

    if "team_id" not in manifest or "sessions" not in manifest:
        return

    team_id = manifest["team_id"]
    github_login = manifest.get("github_login", "")
    if github_login != member_dir.name:
        report.err(
            f"{manifest_path}: manifest.github_login={github_login!r} but parent "
            f"directory is {member_dir.name!r}"
        )

    declared_files: set[Path] = set()

    for idx, session in enumerate(manifest.get("sessions", [])):
        if not isinstance(session, dict):
            continue
        rel_path = session.get("file_path", "")
        sid = session.get("session_id", f"<unknown-{idx}>")
        tool = session.get("tool", "")

        # file_path is "logs/<github_login>/<date>/<tool>__<sid>.jsonl" relative
        # to the demo repo root. We try multiple resolution bases for robustness.
        candidates = [
            repo_root / rel_path,
            member_dir.parent.parent / rel_path,
            member_dir / rel_path.removeprefix(f"logs/{member_dir.name}/"),
        ]
        jsonl_path = None
        for c in candidates:
            if c.exists():
                jsonl_path = c
                break
        if jsonl_path is None:
            report.err(
                f"{manifest_path}: session[{idx}] {sid!r}: declared file_path "
                f"{rel_path!r} does not exist"
            )
            continue

        # Collector versions before 2026-07-10 split one session across
        # daily date files (logs/<login>/<date>/<tool>__<sid>.jsonl) while
        # the manifest kept a single entry with the cumulative count and
        # the last day's file_path. Gather every file of this session so
        # the whole stream is validated together, the cumulative count is
        # compared against the aggregate, and sibling files are not
        # mis-flagged as orphans.
        session_files = {
            p for p in member_dir.glob("*/*.jsonl")
            if p.name == f"{tool}__{sid}.jsonl"
        }
        session_files.add(jsonl_path)
        session_files = sorted(session_files, key=lambda p: (p.parent.name, p.name))

        for sf in session_files:
            declared_files.add(sf.resolve())

        seq_state: dict[str, Any] = {"seen": {}, "last": -1}
        agg_count = 0
        for sf in session_files:
            fstats = validate_jsonl_file(
                sf, event_validator, team_id, github_login, tool, sid, report,
                seq_state=seq_state,
            )
            agg_count += fstats["count"]

        declared_count = session.get("event_count", -1)
        if declared_count != agg_count:
            report.err(
                f"{manifest_path}: session[{idx}] {sid!r}: event_count mismatch: "
                f"manifest={declared_count}, actual={agg_count} "
                f"(aggregated across {len(session_files)} file(s))"
            )

    for jsonl_path in member_dir.rglob("*.jsonl"):
        if jsonl_path.resolve() not in declared_files:
            report.warn(
                f"{jsonl_path}: orphan file (exists but not in manifest.sessions)"
            )


def validate_manifest(
    logs_dir: Path,
    manifest_validator: Draft7Validator,
    event_validator: Draft7Validator,
    report: Report,
) -> None:
    # Two invocation modes are supported:
    #   1. logs_dir = <repo>/logs/        → iterate member subdirs
    #   2. logs_dir = <repo>/logs/<login> → validate that single member only
    if (logs_dir / "manifest.json").exists():
        repo_root = logs_dir.parent.parent
        _validate_one_member(logs_dir, repo_root, manifest_validator, event_validator, report)
        return

    repo_root = logs_dir.parent
    member_dirs = [d for d in logs_dir.iterdir() if d.is_dir() and (d / "manifest.json").exists()]
    if not member_dirs:
        report.err(f"{logs_dir}: no member directories with manifest.json found")
        return
    for member_dir in sorted(member_dirs):
        _validate_one_member(member_dir, repo_root, manifest_validator, event_validator, report)


def main() -> int:
    parser = argparse.ArgumentParser(
        description="Validate contest session log directory"
    )
    parser.add_argument(
        "logs_dir",
        help="Path to demo repo logs/ directory",
    )
    parser.add_argument(
        "--quiet", "-q", action="store_true", help="Only report errors, not warnings"
    )
    args = parser.parse_args()

    logs_dir = Path(args.logs_dir).resolve()
    if not logs_dir.is_dir():
        print(f"ERROR: not a directory: {logs_dir}", file=sys.stderr)
        return 3

    event_schema = load_schema(EVENT_SCHEMA_PATH)
    manifest_schema = load_schema(MANIFEST_SCHEMA_PATH)
    event_validator = Draft7Validator(event_schema)
    manifest_validator = Draft7Validator(manifest_schema)

    report = Report()
    validate_manifest(logs_dir, manifest_validator, event_validator, report)

    print(f"=== contest-log-upload validation ===")
    print(f"Logs dir:       {logs_dir}")
    print(f"Files checked:  {report.files_checked}")
    print(f"Events checked: {report.events_checked}")

    if report.errors:
        print(f"\n❌ ERRORS ({len(report.errors)}):")
        for e in report.errors:
            print(f"  • {e}")

    if report.warnings and not args.quiet:
